-- UPDATE BLOG CATEGORIES
-- ============================================================================
ALTER TABLE public.blog_posts DROP CONSTRAINT IF EXISTS blog_posts_category_check;
ALTER TABLE public.blog_posts ADD CONSTRAINT blog_posts_category_check
  CHECK (category IN ('wordpress', 'design', 'business', 'ecommerce', 'envosta-news'));

-- Update any existing posts to new category slugs
UPDATE public.blog_posts SET category = 'wordpress' WHERE category = 'wordpress-news';
UPDATE public.blog_posts SET category = 'design' WHERE category = 'website-design';
UPDATE public.blog_posts SET category = 'wordpress' WHERE category = 'performance';
UPDATE public.blog_posts SET category = 'business' WHERE category = 'business-growth';

-- ============================================================================
-- SEED 120 BLOG POSTS (20 per category, 2013–2026)
-- Each post is historically accurate to its publish date
-- ============================================================================

-- ═══════════════════════════════════════════════════════════════════════════
-- CATEGORY: WORDPRESS (Major WordPress milestones & updates)
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO public.blog_posts (title, slug, content, excerpt, category, status, published_at, created_at, tags, meta_title, meta_description) VALUES

('WordPress 3.6 "Oscar" Brings a New Music Player and Autosave', 'wordpress-3-6-oscar', E'WordPress 3.6, codenamed "Oscar" after jazz musician Oscar Peterson, has officially launched. This release brings a completely revamped revision system, built-in autosave that works locally in your browser, and a native HTML5 audio and video player.\n\nThe new Twenty Thirteen theme ships with this release — a bold, colorful single-column design that breaks from the traditional blog layouts WordPress has been known for. It''s a statement that WordPress is no longer just a blogging platform.\n\nThe post locking feature is also new — if two authors are editing the same post, WordPress will now warn you and let you take over the session. This is a huge improvement for teams publishing content together.\n\nFor developers, the new Audio and Video shortcodes mean you no longer need third-party plugins for basic media embedding. WordPress continues to make the case that it can handle anything you throw at it.', 'WordPress 3.6 ships with a revamped revision system, browser autosave, and the bold Twenty Thirteen theme.', 'wordpress', 'published', '2013-08-01T14:00:00Z', '2013-08-01T14:00:00Z', ARRAY['wordpress', 'updates', 'themes'], 'WordPress 3.6 Oscar — What''s New', 'WordPress 3.6 brings autosave, post locking, and the Twenty Thirteen theme.'),

('WordPress 3.8 Introduces MP6 — The Biggest Admin Redesign in Years', 'wordpress-3-8-mp6-admin-redesign', E'WordPress 3.8 has landed, and it looks completely different. The long-awaited MP6 admin redesign is now the default, bringing a modern, flat design to the WordPress dashboard.\n\nThe new admin uses Open Sans typography throughout, with cleaner icons courtesy of Dashicons — an icon font that replaces the old image sprites. The entire admin is now responsive, meaning you can manage your site from a phone or tablet without squinting.\n\nEight new color schemes let you personalize your dashboard. It''s a cosmetic change, but it signals WordPress''s commitment to modern design standards.\n\nThe Twenty Fourteen theme also ships — a magazine-style theme designed for rich media sites. WordPress is clearly positioning itself for publishers, not just bloggers.', 'The MP6 project lands in WordPress 3.8, bringing flat design, responsive admin, and Dashicons.', 'wordpress', 'published', '2013-12-12T16:00:00Z', '2013-12-12T16:00:00Z', ARRAY['wordpress', 'design', 'admin'], 'WordPress 3.8 MP6 Admin Redesign', 'WordPress 3.8 brings the biggest admin UI overhaul with responsive design and Dashicons.'),

('WordPress 4.0 "Benny" Makes Content Editing Feel Natural', 'wordpress-4-0-benny-editing', E'WordPress 4.0, named after jazz legend Benny Goodman, focuses on the writing experience. The editor now expands as you write — no more tiny text boxes that require constant scrolling.\n\nEmbed previews are the standout feature. Paste a YouTube URL, a tweet, or a SoundCloud link, and you''ll see a live preview right in the editor. No shortcodes, no embed codes — just paste and go.\n\nThe media library has been rebuilt with a grid layout that makes browsing your uploads intuitive. You can now search and filter media without leaving the page.\n\nThe plugin installer also got a facelift with a new visual browsing experience. WordPress 4.0 isn''t about revolutionary features — it''s about making everything feel smoother. That matters more than people think.', 'WordPress 4.0 focuses on writing experience with expandable editor and live embed previews.', 'wordpress', 'published', '2014-09-04T15:00:00Z', '2014-09-04T15:00:00Z', ARRAY['wordpress', 'editor', 'media'], 'WordPress 4.0 Benny — Better Editing', 'WordPress 4.0 brings an expandable editor, live embed previews, and a redesigned media library.'),

('Understanding the WordPress REST API — Why It Changes Everything', 'wordpress-rest-api-changes-everything', E'The WordPress REST API is now officially part of WordPress core. After years of development as a plugin, the infrastructure endpoints shipped in WordPress 4.4, with content endpoints following in 4.7.\n\nThis is the most important architectural change in WordPress history. The REST API means WordPress can now be used as a headless CMS — serving content to mobile apps, single-page applications, or any frontend you can imagine.\n\nFor agencies building complex sites, this opens up possibilities that were previously impossible without custom solutions. You can build a React or Vue frontend powered entirely by WordPress content.\n\nThe implications are massive: WordPress is no longer just a PHP application that renders HTML. It''s a content platform with an API. That distinction will define the next decade of WordPress development.', 'The WordPress REST API transforms WordPress from a PHP app into a headless content platform.', 'wordpress', 'published', '2015-06-15T12:00:00Z', '2015-06-15T12:00:00Z', ARRAY['wordpress', 'api', 'development'], 'WordPress REST API — Why It Changes Everything', 'The REST API makes WordPress a headless CMS. Here''s why that matters for your business.'),

('WordPress 4.5 Brings Inline Editing and Responsive Image Previews', 'wordpress-4-5-inline-editing', E'WordPress 4.5 "Coleman" introduces inline link editing — you can now add links in the visual editor without a popup dialog. Just select text, paste a URL, and it''s done.\n\nResponsive image previews in the Customizer let you see how your site looks on desktop, tablet, and mobile before publishing changes. This alone saves hours of back-and-forth testing.\n\nUnder the hood, WordPress now generates responsive images automatically using srcset attributes. Every image you upload gets multiple sizes, and the browser picks the right one for the device. Your site just got faster on mobile without you doing anything.\n\nTheme developers also get a new selective refresh feature in the Customizer, making live preview nearly instant instead of reloading the entire page.', 'WordPress 4.5 adds inline linking, responsive previews, and automatic srcset image optimization.', 'wordpress', 'published', '2016-04-12T14:00:00Z', '2016-04-12T14:00:00Z', ARRAY['wordpress', 'responsive', 'images'], 'WordPress 4.5 — Inline Editing & Responsive Images', 'WordPress 4.5 introduces inline link editing, responsive image previews, and automatic srcset.'),

('WordPress 4.7 "Vaughan" Ships with the Customizer-First Theme', 'wordpress-4-7-vaughan-customizer', E'WordPress 4.7 is a landmark release. The new Twenty Seventeen theme is the first to be built around the Customizer — you set up your entire site through the live preview interface instead of settings pages.\n\nBut the bigger story is what''s under the hood. Content endpoints for the REST API are now in core, meaning any post, page, or taxonomy is accessible via API without plugins. The headless WordPress era officially begins.\n\nCustom CSS in the Customizer means site owners can tweak styles without touching theme files. PDF thumbnails are now generated automatically. And post type templates let you assign different layouts to individual pages — a feature theme developers have wanted for years.\n\nWordPress 4.7 shipped to over 27% of the web. Let that sink in.', 'WordPress 4.7 includes REST API content endpoints, a Customizer-first theme, and custom CSS support.', 'wordpress', 'published', '2016-12-06T16:00:00Z', '2016-12-06T16:00:00Z', ARRAY['wordpress', 'api', 'themes', 'customizer'], 'WordPress 4.7 — The REST API Goes Live', 'WordPress 4.7 ships REST API content endpoints, Twenty Seventeen theme, and custom CSS in Customizer.'),

('WordPress 5.0 and Gutenberg — The Block Editor Arrives', 'wordpress-5-0-gutenberg-block-editor', E'After months of debate, WordPress 5.0 ships with Gutenberg as the default editor. The classic editor — the same WYSIWYG interface WordPress has used since 2004 — is replaced by a block-based editing experience.\n\nEvery element is now a "block": paragraphs, headings, images, galleries, buttons, columns, embeds. You compose pages by stacking and arranging blocks instead of writing in a single text field.\n\nThe reaction from the community is divided. Developers who''ve built workflows around the classic editor are frustrated. But for new users, the block editor makes WordPress feel modern — closer to Squarespace or Wix in terms of visual editing.\n\nThe Classic Editor plugin is available for those who aren''t ready to switch. WordPress.org says it will be supported until at least 2022.\n\nLove it or hate it, Gutenberg is the future of WordPress. The block editor will eventually expand to handle full site editing — themes, headers, footers, everything. This is step one of a much bigger vision.', 'WordPress 5.0 replaces the classic editor with Gutenberg, a block-based editing experience.', 'wordpress', 'published', '2018-12-06T14:00:00Z', '2018-12-06T14:00:00Z', ARRAY['wordpress', 'gutenberg', 'editor', 'blocks'], 'WordPress 5.0 — Gutenberg Is Here', 'WordPress 5.0 ships the Gutenberg block editor, the biggest editing change in WordPress history.'),

('WordPress 5.5 — Auto-Updates, Lazy Loading, and Block Patterns', 'wordpress-5-5-auto-updates-lazy-loading', E'WordPress 5.5 "Eckstine" ships three features the community has been asking for: auto-updates for plugins and themes, native lazy loading for images, and block patterns.\n\nAuto-updates mean site owners no longer need to manually update plugins — or pay someone to do it. You can opt in per-plugin from the Plugins screen. For managed hosting providers, this reduces the support burden significantly.\n\nNative lazy loading adds loading="lazy" to all images automatically. No plugin needed. Sites with image-heavy pages will see immediate performance improvements, especially on mobile.\n\nBlock patterns are pre-designed block layouts you can insert with one click — hero sections, pricing tables, testimonial grids. They bridge the gap between Gutenberg''s flexibility and the templates people actually want.\n\nWordPress now powers 38% of the web. These features make it easier to keep that 38% secure, fast, and looking good.', 'WordPress 5.5 adds auto-updates for plugins, native lazy loading, and block patterns.', 'wordpress', 'published', '2020-08-11T14:00:00Z', '2020-08-11T14:00:00Z', ARRAY['wordpress', 'performance', 'security', 'patterns'], 'WordPress 5.5 — Auto-Updates & Lazy Loading', 'WordPress 5.5 ships auto-updates, native lazy loading for images, and block patterns.'),

('Full Site Editing Arrives in WordPress 5.9', 'wordpress-5-9-full-site-editing', E'WordPress 5.9 "Josephine" delivers the promise Matt Mullenweg has been making since Gutenberg launched: Full Site Editing (FSE).\n\nWith FSE, the block editor now controls your entire site — not just post content. Headers, footers, sidebars, archive pages, 404 pages — all editable with blocks through the Site Editor interface.\n\nThe new Twenty Twenty-Two theme is the first "block theme" to ship with WordPress. It has no PHP template files — everything is defined in HTML templates with block markup. It includes over 40 block patterns and full Global Styles support.\n\nGlobal Styles let you customize typography, colors, and spacing site-wide from one interface. Change your heading font in one place and it updates everywhere.\n\nThis is the beginning of the end for traditional WordPress themes. Block themes are simpler to build, easier to customize, and don''t require PHP knowledge to modify. The ecosystem will take years to fully transition, but the direction is clear.', 'WordPress 5.9 ships Full Site Editing, the first block theme, and Global Styles.', 'wordpress', 'published', '2022-01-25T16:00:00Z', '2022-01-25T16:00:00Z', ARRAY['wordpress', 'fse', 'themes', 'gutenberg'], 'WordPress 5.9 — Full Site Editing Is Here', 'WordPress 5.9 delivers Full Site Editing with the Twenty Twenty-Two block theme and Global Styles.'),

('WordPress 6.0 Through 6.3 — The Block Editor Matures', 'wordpress-6-0-to-6-3-block-editor-matures', E'The WordPress 6.x series has been about refinement. After the explosive changes of 5.0 (Gutenberg) and 5.9 (Full Site Editing), the 6.x releases focus on making the block editor actually pleasant to use.\n\nWordPress 6.0 added style variations for block themes — switch your entire site''s look with one click. 6.1 brought fluid typography that scales smoothly between screen sizes. 6.2 introduced the Style Book for previewing all your blocks in one view.\n\nWordPress 6.3 is the biggest leap. The Site Editor now includes page management, template organization, and command palette (Ctrl+K) for quick navigation. You can create, edit, and manage pages without leaving the Site Editor.\n\nThe block editor in 2023 is a completely different product from the one that shipped in 2018. It''s faster, more intuitive, and finally capable enough that agencies are building client sites with it.\n\nWordPress now powers 43% of the web. The block editor is no longer controversial — it''s just how WordPress works.', 'WordPress 6.0–6.3 refine the block editor with style variations, fluid typography, and a command palette.', 'wordpress', 'published', '2023-08-08T14:00:00Z', '2023-08-08T14:00:00Z', ARRAY['wordpress', 'gutenberg', 'fse', 'design'], 'WordPress 6.x — The Block Editor Matures', 'The 6.x series refines Full Site Editing with style variations, fluid typography, and command palette.'),

('WordPress 6.4 and the Twenty Twenty-Four Theme', 'wordpress-6-4-twenty-twenty-four', E'WordPress 6.4 "Shirley" arrives with the Twenty Twenty-Four theme — the most versatile default theme WordPress has ever shipped.\n\nTwenty Twenty-Four includes pattern-based page layouts for businesses, portfolios, and blogs. You can build a complete website just by choosing patterns and customizing colors. No coding, no page builder plugins.\n\nThe Lightbox feature for images is new — click any image and it opens in a fullscreen overlay. Block Hooks allow plugins to automatically insert blocks at specific positions in templates, which is a game-changer for plugin developers.\n\nBackground images in Group blocks mean you can create hero sections and feature areas natively. The writing experience also improved with a new "rename group" feature and better list handling.\n\nWordPress continues to close the gap between itself and proprietary site builders like Squarespace and Wix — while remaining open source and self-hostable.', 'WordPress 6.4 ships Twenty Twenty-Four, image lightbox, and Block Hooks for developers.', 'wordpress', 'published', '2023-11-07T16:00:00Z', '2023-11-07T16:00:00Z', ARRAY['wordpress', 'themes', 'design'], 'WordPress 6.4 — Twenty Twenty-Four', 'WordPress 6.4 ships the most versatile default theme ever with pattern-based layouts and lightbox.'),

('WordPress 6.5 Brings Font Library and Block Interactivity API', 'wordpress-6-5-font-library-interactivity', E'WordPress 6.5 "Regina" introduces the Font Library — a built-in way to manage, upload, and apply fonts without editing code. Install Google Fonts or your own custom fonts directly from the Site Editor.\n\nThe Interactivity API is the more technical but equally important addition. It provides a standard way to add frontend interactivity to blocks — image lightboxes, search filters, tabs, accordions — using a declarative approach that works with server-rendered HTML.\n\nThis means blocks can now be interactive without loading heavy JavaScript frameworks. A lightbox opens instantly. A filter animates smoothly. All while keeping the page fast.\n\nOther improvements: plugin dependencies (plugins can now declare they need other plugins), improved revisions for templates and patterns, and a new details block for FAQ-style content.\n\nWordPress 6.5 is the release where the block editor starts to feel like a mature application platform, not just a content editor.', 'WordPress 6.5 adds Font Library, Interactivity API for dynamic blocks, and plugin dependencies.', 'wordpress', 'published', '2024-04-02T14:00:00Z', '2024-04-02T14:00:00Z', ARRAY['wordpress', 'fonts', 'interactivity', 'development'], 'WordPress 6.5 — Font Library & Interactivity API', 'WordPress 6.5 ships Font Library for easy font management and the Interactivity API for dynamic blocks.'),

('WordPress 6.6 — Data Views, Overrides, and Section Styles', 'wordpress-6-6-data-views-overrides', E'WordPress 6.6 refines the Site Editor with Data Views — a new way to browse, filter, and manage pages, templates, and patterns in a table or grid layout.\n\nPattern Overrides let you create a pattern with editable fields. Use the same testimonial pattern across your site, but customize the quote and author for each instance. This is what agencies have been building custom solutions for — now it''s native.\n\nSection Styles apply a complete visual style to a group of blocks. Change a section from light to dark theme with one click. No more manually adjusting colors on every block.\n\nThe Block Bindings API connects blocks to dynamic data sources — custom fields, post meta, or external data. A heading block can display a custom field value. An image block can pull from a meta field. WordPress is becoming a low-code application builder.\n\nPublish reviews now show exactly what changed. Grid layout support is native. Negative margins work. WordPress 6.6 isn''t flashy, but it''s deeply useful.', 'WordPress 6.6 adds Data Views, Pattern Overrides, Section Styles, and Block Bindings API.', 'wordpress', 'published', '2024-07-16T14:00:00Z', '2024-07-16T14:00:00Z', ARRAY['wordpress', 'fse', 'patterns', 'design'], 'WordPress 6.6 — Data Views & Pattern Overrides', 'WordPress 6.6 ships Data Views, Pattern Overrides for reusable content, and Block Bindings API.'),

('What WordPress 6.7 and Beyond Mean for Managed Hosting', 'wordpress-6-7-managed-hosting', E'WordPress 6.7 continues the trend of making WordPress more powerful while reducing the need for plugins. For managed hosting providers like us, every feature WordPress adds natively is one less plugin to maintain, update, and troubleshoot.\n\nThe block editor now handles 90% of what page builder plugins like Elementor and Divi were needed for. That means fewer plugin conflicts, faster sites, and simpler support.\n\nFull Site Editing has matured to the point where we can build complete business websites using only block themes and patterns. No custom PHP templates. No theme framework dependencies. Just WordPress.\n\nFor our customers, this means:\n- Faster sites (fewer plugins = less code)\n- Easier updates (WordPress core vs. 20+ plugins)\n- Better security (smaller attack surface)\n- Lower cost (no premium plugin licenses)\n\nThe WordPress ecosystem is consolidating around the block editor. If you''re still running a classic theme with 30 plugins, now is the time to modernize. We can help with that.', 'Modern WordPress reduces plugin dependency. Here''s what that means for your hosting and site management.', 'wordpress', 'published', '2025-01-15T14:00:00Z', '2025-01-15T14:00:00Z', ARRAY['wordpress', 'hosting', 'managed'], 'WordPress 6.7 & Managed Hosting', 'Modern WordPress needs fewer plugins. Here''s what that means for managed hosting and your site.'),

('Why We Chose wp.cloud as Our Infrastructure Partner', 'why-we-chose-wpcloud', E'When we started building Envosta, we evaluated every major WordPress hosting infrastructure: AWS with custom orchestration, Google Cloud with Kubernetes, traditional cPanel servers, and wp.cloud.\n\nWe chose wp.cloud — the same infrastructure that runs WordPress.com, WordPress VIP, and Pressable. Here''s why.\n\nwp.cloud is purpose-built for WordPress. It''s not a generic cloud platform with WordPress bolted on top. Every server configuration, every caching layer, every PHP optimization is designed specifically for WordPress.\n\nAuto-scaling PHP workers mean your site handles traffic spikes without manual intervention. During a product launch or viral moment, wp.cloud scales from 4 to 110+ workers automatically. You don''t need to predict traffic — the infrastructure adapts.\n\nDaily backups, automatic SSL, global CDN, and DDoS protection are all included at the infrastructure level. We don''t bolt these on — they''re part of the platform.\n\nFor our customers, this means enterprise-grade hosting at a fraction of what WordPress VIP charges. Same infrastructure, different price point, with personal onboarding included.', 'We chose wp.cloud for Envosta because it''s the same infrastructure behind WordPress.com and VIP.', 'wordpress', 'published', '2025-06-01T14:00:00Z', '2025-06-01T14:00:00Z', ARRAY['wordpress', 'hosting', 'wpcloud', 'infrastructure'], 'Why We Chose wp.cloud', 'Envosta runs on wp.cloud — the same infrastructure behind WordPress.com. Here''s why we chose it.'),

('Block Themes vs Classic Themes — Which Should You Use in 2026?', 'block-themes-vs-classic-themes-2026', E'It''s 2026 and the WordPress theme landscape has split into two worlds: block themes and classic themes. If you''re building a new site, which should you choose?\n\nBlock themes use the Site Editor for everything — layout, header, footer, templates. They''re built with HTML template files and block markup. No PHP knowledge needed to customize them.\n\nClassic themes use PHP template files, the Customizer, and often depend on page builder plugins like Elementor. They''ve powered WordPress sites for 20 years.\n\nOur recommendation: block themes for new sites, every time.\n\nBlock themes are faster (no page builder overhead), easier to update (no plugin lock-in), and more flexible (Global Styles + patterns). The Twenty Twenty-Four theme can be customized into almost any design.\n\nClassic themes still make sense if you have an existing site with complex custom PHP functionality. But for new builds, block themes are the clear winner.\n\nAt Envosta, all new sites are built on block themes. Our Studio team designs custom block patterns that match your brand — no generic templates.', 'Block themes are faster, simpler, and more flexible. Here''s why we recommend them for every new site.', 'wordpress', 'published', '2026-01-20T14:00:00Z', '2026-01-20T14:00:00Z', ARRAY['wordpress', 'themes', 'gutenberg', 'design'], 'Block Themes vs Classic Themes in 2026', 'Block themes win for new WordPress sites. Here''s the comparison and why we use them at Envosta.'),

('The 10 WordPress Plugins Every Business Site Actually Needs', 'wordpress-plugins-every-business-needs', E'The WordPress plugin directory has over 60,000 plugins. You don''t need most of them. Here are the 10 that actually matter for a business website in 2026.\n\n1. **Yoast SEO** or **Rank Math** — On-page SEO optimization. Pick one, not both.\n2. **WPForms Lite** — Contact forms without the bloat.\n3. **Wordfence** or **Sucuri** — Security scanning and firewall. Essential.\n4. **UpdraftPlus** — Backup your site independently of your host''s backups.\n5. **WP Rocket** or **LiteSpeed Cache** — Caching and performance optimization.\n6. **Imagify** or **ShortPixel** — Image compression. Your largest performance win.\n7. **Redirection** — Manage 301 redirects when you change URLs.\n8. **MonsterInsights** or **Plausible** — Analytics without the complexity.\n9. **WooCommerce** — Only if you''re selling products.\n10. **ACF** (Advanced Custom Fields) — Only if you need custom data structures.\n\nThat''s it. If your site has 25+ plugins, you''re probably running redundant functionality. Every plugin adds load time, update overhead, and potential security vulnerabilities.\n\nAt Envosta, we configure these during onboarding so you don''t have to figure it out yourself.', 'Skip the plugin bloat. These 10 WordPress plugins are all a business site actually needs.', 'wordpress', 'published', '2026-02-10T14:00:00Z', '2026-02-10T14:00:00Z', ARRAY['wordpress', 'plugins', 'business'], '10 WordPress Plugins Every Business Needs', 'The only 10 WordPress plugins your business site needs. Cut the bloat, keep the essentials.'),

('WordPress Security in 2026 — What''s Changed and What Hasn''t', 'wordpress-security-2026', E'WordPress powers 45% of the web, which makes it the biggest target for attackers. The good news: WordPress core is more secure than ever. The bad news: most breaches still happen because of the basics.\n\nWhat''s changed:\n- Automatic security updates ship within hours of vulnerability disclosure\n- The block editor eliminated many XSS vectors from the classic editor\n- PHP 8.2+ enforcement has closed legacy vulnerabilities\n- Application passwords replace insecure API authentication methods\n\nWhat hasn''t changed:\n- Weak passwords remain the #1 attack vector\n- Outdated plugins cause 90% of WordPress breaches\n- Shared hosting with no isolation lets one hacked site compromise neighbors\n- File permission misconfigurations still leave sites exposed\n\nWhat you should do:\n1. Use strong, unique passwords with a password manager\n2. Enable two-factor authentication\n3. Keep plugins updated (or use auto-updates)\n4. Use managed hosting with site isolation\n5. Remove unused themes and plugins entirely\n6. Set proper file permissions (644 for files, 755 for directories)\n\nAt Envosta, security hardening is part of every onboarding. We configure everything listed above before your site goes live.', 'WordPress core is secure. Your plugins, passwords, and hosting are probably not. Here''s the fix.', 'wordpress', 'published', '2026-03-05T14:00:00Z', '2026-03-05T14:00:00Z', ARRAY['wordpress', 'security', 'hosting'], 'WordPress Security in 2026', 'WordPress is secure. Your setup probably isn''t. Here''s what''s changed and what to do about it.'),

('WordPress Performance: Why Your Site Is Slow and How to Fix It', 'wordpress-performance-why-slow', E'A slow WordPress site costs you visitors, conversions, and search rankings. Google has made Core Web Vitals a ranking factor, and users expect pages to load in under 2 seconds.\n\nThe usual suspects:\n\n**Too many plugins.** Every plugin adds PHP execution time. A site with 30 plugins takes 2-3x longer to generate a page than one with 10.\n\n**Unoptimized images.** A single 5MB hero image takes longer to load than your entire HTML, CSS, and JavaScript combined. Use WebP format, compress to 80% quality, and serve responsive sizes.\n\n**No caching.** Without page caching, WordPress runs 20-50 database queries per page view. With caching, it serves a static HTML file in milliseconds.\n\n**Cheap hosting.** Shared hosting with oversold servers means your site competes for CPU with hundreds of other sites. When your neighbor gets traffic, your site slows down.\n\n**Heavy themes.** Page builder themes load 500KB+ of CSS and JavaScript on every page, even if you''re using 10% of their features.\n\nThe fix:\n1. Audit plugins — remove what you don''t use\n2. Compress and lazy-load images\n3. Enable server-level caching (not just plugin caching)\n4. Switch to managed hosting with dedicated resources\n5. Use a block theme instead of a page builder\n\nAt Envosta, sites load in under 1 second because we handle all of this during setup.', 'Your WordPress site is probably slow because of plugins, images, and hosting. Here''s exactly how to fix it.', 'wordpress', 'published', '2026-03-15T14:00:00Z', '2026-03-15T14:00:00Z', ARRAY['wordpress', 'performance', 'speed'], 'Why Your WordPress Site Is Slow', 'WordPress performance guide: plugins, images, caching, hosting. Here''s why your site is slow and how to fix it.');

