INSERT INTO public.blog_posts (title, slug, content, excerpt, category, status, published_at, created_at, tags, meta_title, meta_description) VALUES

('Introducing Envosta — Managed WordPress Hosting With a Personal Touch', 'introducing-envosta', E'Today we''re launching Envosta — managed WordPress hosting built on enterprise infrastructure with personal onboarding included on every plan.\n\nWe built Envosta because we saw a gap in the market. On one side, you have cheap shared hosting where you''re on your own. On the other, you have premium managed hosting that costs $100+/month but still expects you to build your own site.\n\nEnvosta is different. Every plan starts with a consultation. We learn about your business, set up your site, configure security and performance, and hand you something that''s ready to go.\n\nOur infrastructure runs on wp.cloud — the same platform behind WordPress.com and WordPress VIP. Auto-scaling PHP workers, global CDN, daily backups, and 99.99% uptime. Enterprise performance at small business prices.\n\n**Our plans:**\n- **Minimum** ($50 CAD/mo): Perfect for personal sites and small businesses. Includes consultation, WordPress install, and full configuration.\n- **Growth** ($129 CAD/mo): For growing businesses. Guided onboarding, SEO setup, plugin recommendations, performance optimization.\n- **Performance** ($350 CAD/mo): Concierge service. Custom theme design, WooCommerce setup, security hardening, dedicated account manager.\n\n**14-day free trial** available on the Minimum plan. No risk, no commitment.\n\nWe''re a small team in Calgary, Alberta, and we answer the phone. Try us.', 'Envosta launches: managed WordPress hosting with personal onboarding on enterprise infrastructure.', 'envosta-news', 'published', '2026-03-18T14:00:00Z', '2026-03-18T14:00:00Z', ARRAY['envosta', 'launch', 'hosting', 'announcement'], 'Introducing Envosta', 'Envosta launches: managed WordPress hosting on wp.cloud with personal onboarding. Starting at $50 CAD/mo.'),

('Envosta Studio — We Don''t Just Host. We Build.', 'envosta-studio-launch', E'Today we''re announcing Envosta Studio — a design and development service for customers who want their website built, not just hosted.\n\nHere''s how it works:\n\n1. Submit a studio request describing what you need\n2. We review your request and send a quote (usually within 24 hours)\n3. You approve the quote\n4. Our team designs and builds it (3-5 business days for most requests)\n5. You review, we revise, and it goes live\n\n**What you can request:**\n- Page design and redesigns\n- New features and functionality\n- WooCommerce store setup\n- Plugin configuration\n- Content updates and copywriting\n- Performance optimization\n- Security hardening\n\n**Pricing:** Studio requests start at $250 CAD per request. Complex projects are quoted individually.\n\nStudio is available to all Envosta hosting customers. Submit a request from your dashboard under Requests & Support → New Studio Request.\n\nWe built Studio because our customers kept asking: "Can you just do this for me?" Now we can. Your website is handled — hosting, design, development, and support. One team, one relationship.', 'Envosta Studio: submit design and development requests from your dashboard. Starting at $250 CAD.', 'envosta-news', 'published', '2026-03-19T14:00:00Z', '2026-03-19T14:00:00Z', ARRAY['envosta', 'studio', 'design', 'development'], 'Envosta Studio Launch', 'Envosta Studio: design and development requests handled by our team. Starting at $250 CAD.'),

('Domain Registration Now Available Through Envosta', 'domain-registration-envosta', E'You can now register and manage domains directly through your Envosta dashboard. No more juggling between a domain registrar and your hosting provider.\n\n**What''s included:**\n- Registration for 20+ TLDs (.com, .ca, .net, .io, .co, and more)\n- Auto-renew management\n- DNS configuration\n- Nameserver management\n- WHOIS privacy\n- Automatic wp.cloud DNS setup when connected to a site\n\n**Pricing:** Domain registration starts at $15 CAD/year for .com domains. All prices are in CAD with no hidden fees.\n\n**Free with hosting:** When you sign up for a hosting plan, your first year of domain registration is included free. We register the domain during onboarding and configure DNS automatically.\n\n**How it works:**\n1. Search for your domain in the dashboard\n2. Register with one click\n3. DNS records for your wp.cloud site are configured automatically\n4. SPF, DKIM, and DMARC email records are set up for you\n\nNo more copying DNS records between providers. No more waiting for propagation. It just works.\n\nDomain management is available now in your Envosta dashboard under Domains.', 'Register and manage domains directly from your Envosta dashboard. Free with your first hosting plan.', 'envosta-news', 'published', '2026-03-20T14:00:00Z', '2026-03-20T14:00:00Z', ARRAY['envosta', 'domains', 'dns', 'feature'], 'Domain Registration on Envosta', 'Register domains from your Envosta dashboard. Auto-DNS, email records, and free with hosting.'),

('New: 14-Day Free Trial on the Minimum Plan', 'free-trial-minimum-plan', E'Starting today, you can try Envosta free for 14 days on our Minimum plan.\n\nHere''s what you get during the trial:\n- A fully provisioned WordPress site on wp.cloud infrastructure\n- Temporary domain (yoursitename.envosta.cloud)\n- All Minimum plan features: staging, backups, CDN, SSL\n- Full dashboard access\n- Support from our team\n\n**No charge for 14 days.** Your credit card is required to start the trial, but you won''t be charged until day 15. Cancel anytime during the trial and pay nothing.\n\nAfter the trial, your site continues on the Minimum plan at $50 CAD/month. Or upgrade to Growth ($129/mo) or Performance ($350/mo) for more resources and hands-on support.\n\n**Why we''re doing this:**\nWe believe managed hosting sells itself once you experience it. The difference between a sub-1-second site on dedicated infrastructure and a 3-second site on shared hosting is obvious. We want you to feel that difference before you commit.\n\nStart your free trial at envosta.com/get-started.', 'Try Envosta free for 14 days. Full Minimum plan features, no charge until day 15.', 'envosta-news', 'published', '2026-03-25T14:00:00Z', '2026-03-25T14:00:00Z', ARRAY['envosta', 'trial', 'pricing', 'announcement'], '14-Day Free Trial', 'Try Envosta free for 14 days on the Minimum plan. Full features, cancel anytime.');

